import type { BillingProfile, Company, Dataset, Member, Project, RateEntry, TimeEntry } from '../../domain/types.ts';
import company from './company.json';
import members from './members.json';
import projects from './projects.json';
import rates from './rates.json';
import timeEntries from './time-entries.json';
import billingProfiles from './billing-profiles.json';

/** Initial data bundled with the app (all fictional). Generated by scripts/generate-data.ts. */
export function seedDataset(): Dataset {
  return structuredClone({
    company: company as Company,
    members: members as Member[],
    projects: projects as Project[],
    rates: rates as RateEntry[],
    timeEntries: timeEntries as TimeEntry[],
    billingProfiles: billingProfiles as BillingProfile[],
  });
}
